import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export function openProjectStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const database = new DatabaseSync(path);
  database.exec(`
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS projects (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL CHECK (length(trim(name)) > 0)
    );
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL CHECK (length(trim(title)) > 0),
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id);
  `);
  const list = database.prepare('SELECT id, name FROM projects ORDER BY id');
  const find = database.prepare('SELECT id, name FROM projects WHERE id = ?');
  const insert = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
  const findTask = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
  const taskRecord = (task) => task && { ...task, completed: Boolean(task.completed) };

  return {
    list: () => list.all(),
    find: (id) => find.get(id),
    create(name) {
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) {
        throw new Error('Project name is required');
      }
      return find.get(insert.run(trimmedName).lastInsertRowid);
    },
    listTasks: (projectId) => listTasks.all(projectId).map(taskRecord),
    createTask(projectId, title) {
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) throw new Error('Task title is required');
      const result = insertTask.run(projectId, trimmedTitle);
      return taskRecord(findTask.get(projectId, result.lastInsertRowid));
    },
    setTaskCompletion(projectId, taskId, completed) {
      if (typeof completed !== 'boolean') throw new Error('Task completion must be a boolean');
      updateTask.run(Number(completed), projectId, taskId);
      return taskRecord(findTask.get(projectId, taskId));
    },
    close: () => database.close(),
  };
}
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { openProjectStore } from './project-store.js';

const store = openProjectStore(process.env.DB_PATH || 'data/workboard.sqlite');
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/styles.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/styles.css', import.meta.url))]],
]);

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (Buffer.byteLength(body) > 64 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    const error = new Error('Invalid JSON');
    error.status = 400;
    throw error;
  }
}

const server = createServer(async (request, response) => {
  try {
    const pathname = new URL(request.url, 'http://localhost').pathname;
    if (request.method === 'GET' && pathname === '/health') {
      return json(response, 200, { status: 'ok' });
    }
    if (pathname === '/api/projects') {
      if (request.method === 'GET') return json(response, 200, store.list());
      if (request.method === 'POST') {
        const input = await readJson(request);
        if (typeof input?.name !== 'string' || !input.name.trim()) {
          return json(response, 400, { error: 'Project name is required' });
        }
        return json(response, 201, store.create(input.name));
      }
    }
    const tasksApi = pathname.match(/^\/api\/projects\/([1-9]\d*)\/tasks(?:\/([1-9]\d*))?$/);
    if (tasksApi) {
      const [, projectId, taskId] = tasksApi;
      if (!store.find(projectId)) return json(response, 404, { error: 'Project not found' });
      if (!taskId && request.method === 'GET') {
        return json(response, 200, store.listTasks(projectId));
      }
      if (!taskId && request.method === 'POST') {
        const input = await readJson(request);
        if (typeof input?.title !== 'string' || !input.title.trim()) {
          return json(response, 400, { error: 'Task title is required' });
        }
        return json(response, 201, store.createTask(projectId, input.title));
      }
      if (taskId && request.method === 'PATCH') {
        const input = await readJson(request);
        if (typeof input?.completed !== 'boolean') {
          return json(response, 400, { error: 'Task completion must be a boolean' });
        }
        const task = store.setTaskCompletion(projectId, taskId, input.completed);
        return task
          ? json(response, 200, task)
          : json(response, 404, { error: 'Task not found' });
      }
    }
    const projectApi = pathname.match(/^\/api\/projects\/([1-9]\d*)$/);
    if (request.method === 'GET' && projectApi) {
      const project = store.find(projectApi[1]);
      return project
        ? json(response, 200, project)
        : json(response, 404, { error: 'Project not found' });
    }
    if (request.method === 'GET') {
      const asset = assets.get(/^\/projects\/[1-9]\d*$/.test(pathname) ? '/' : pathname);
      if (asset) {
        response.writeHead(200, { 'Content-Type': asset[0] });
        return response.end(asset[1]);
      }
    }
    json(response, 404, { error: 'Not found' });
  } catch (error) {
    if (!error.status) console.error(error);
    json(response, error.status || 500, {
      error: error.status ? error.message : 'Unable to complete the request',
    });
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});

function shutdown() {
  server.close(() => {
    store.close();
    process.exit(0);
  });
  server.closeIdleConnections();
}

process.once('SIGINT', shutdown);
process.once('SIGTERM', shutdown);
const app = document.querySelector('#app');

async function api(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete the request');
  return body;
}

function showError(container, message) {
  container.textContent = message;
  container.hidden = false;
}

function projectRow(project) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const open = document.createElement('button');
  open.type = 'button';
  open.textContent = 'Open project';
  open.addEventListener('click', () => {
    window.location.assign(`/projects/${project.id}`);
  });
  row.append(name, open);
  return row;
}

async function renderProjects() {
  app.innerHTML = `
    <h1>Workboard</h1>
    <section aria-labelledby="projects-heading">
      <h2 id="projects-heading">Projects</h2>
      <form>
        <label for="project-name">Project name</label>
        <div class="create-controls">
          <input id="project-name" name="name" type="text" autocomplete="off">
          <button type="submit">Create project</button>
        </div>
      </form>
      <p role="alert" hidden></p>
      <ul aria-label="Projects"></ul>
    </section>`;
  const form = app.querySelector('form');
  const input = app.querySelector('input');
  const button = form.querySelector('button');
  const alert = app.querySelector('[role="alert"]');
  const list = app.querySelector('ul');
  // Load before accepting writes so a late list response cannot duplicate a new row.
  button.disabled = true;
  try {
    const projects = await api('/api/projects');
    list.append(...projects.map(projectRow));
    button.disabled = false;
  } catch (error) {
    showError(alert, error.message);
  }
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (button.disabled) return;
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      showError(alert, 'Project name is required');
      input.focus();
      return;
    }
    button.disabled = true;
    try {
      const project = await api('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      list.append(projectRow(project));
      input.value = '';
      input.focus();
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = false;
    }
  });
}

async function renderProject(id) {
  app.innerHTML = '<button type="button">Projects</button><h1></h1><p role="alert" hidden></p>';
  app.querySelector('button').addEventListener('click', () => window.location.assign('/'));
  try {
    const project = await api(`/api/projects/${id}`);
    app.querySelector('h1').textContent = project.name;
    document.title = `${project.name} · Workboard`;
    await renderTasks(id);
  } catch (error) {
    app.querySelector('h1').textContent = 'Project unavailable';
    showError(app.querySelector('[role="alert"]'), error.message);
  }
}

async function renderTasks(projectId) {
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Tasks');
  section.innerHTML = `
    <form>
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div class="task-filter">
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option value="all">All</option>
        <option value="open">Open</option>
        <option value="completed">Completed</option>
      </select>
    </div>
    <ul aria-label="Tasks"></ul>`;
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const button = form.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  const filter = section.querySelector('select');
  const list = section.querySelector('ul');
  const path = `/api/projects/${projectId}/tasks`;
  let tasks = [];
  const pendingUpdates = new Set();

  function renderList() {
    const matching = tasks.filter((task) => filter.value === 'all'
      || (filter.value === 'completed' ? task.completed : !task.completed));
    list.replaceChildren(...matching.map((task) => {
      const row = document.createElement('li');
      row.dataset.testid = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = pendingUpdates.has(task.id);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        pendingUpdates.add(task.id);
        alert.hidden = true;
        try {
          const updated = await api(`${path}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = updated.completed;
        } catch (error) {
          checkbox.checked = task.completed;
          showError(alert, error.message);
        } finally {
          pendingUpdates.delete(task.id);
          checkbox.disabled = false;
          // Refresh filtered or replaced rows; otherwise preserve the focused checkbox.
          if (filter.value !== 'all' || !checkbox.isConnected) renderList();
        }
      });
      row.append(title, checkbox);
      return row;
    }));
  }

  filter.addEventListener('change', renderList);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (button.disabled) return;
    alert.hidden = true;
    const title = input.value.trim();
    if (!title) {
      showError(alert, 'Task title is required');
      input.focus();
      return;
    }
    button.disabled = true;
    try {
      tasks.push(await api(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      }));
      renderList();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = false;
    }
  });
  try {
    tasks = await api(path);
    renderList();
    button.disabled = false;
  } catch (error) {
    showError(alert, error.message);
  }
}

const projectPath = window.location.pathname.match(/^\/projects\/([1-9]\d*)$/);
try {
  if (projectPath) await renderProject(projectPath[1]);
  else await renderProjects();
} finally {
  app.setAttribute('aria-busy', 'false');
}
